      role1 = 106000,
      role2 = 101105,
      role3 = 101201,
      roleanim = 1.1,
      sentence = "The edge of the stove was crusted with half a pot of burnt and unrecognizable food. I couldn't help but go wide-eyed and look over at a scowling Victor.",
