  [421184] = {
    [1] = {
      beijing = 1673,
      dialog = 3,
      music = "35_DS_Jazz",
      renwu = "npc",
      sentence = "米酒依然温热，点心也还剩半盒。",
      next = {2}
    },
    [2] = {
      beijing = 1673,
      dialog = 3,
      music = "35_DS_Jazz",
      renwu = "npc",
      sentence = "甜蜜感充斥着整个空间，我发出一声舒然的喟叹，为自己和他各倒了一小杯米酒。",
      next = {3}
    },
    [3] = {
      beijing = 1673,
      dialog = 3,
      music = "35_DS_Jazz",
      renwu = "npc",
      sentence = "品尝之余，我的视线好奇地落在许墨电脑的屏幕上——上面是我看不懂的论文，他身旁还翻开一本有标本插图的书。 ",
      next = {4}
    },
    [4] = {
      beijing = 1673,
      dhead = 107,
      dialog = 1,
      music = "35_DS_Jazz",
      renming = "$u",
      renwu = "npc",
      sentence = "你在看什么书呀？",
      next = {5}
    },
    [5] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201105,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      ruchang = -1,
      sentence = "标本制作方面的文献。",
      voice = 2,
      next = {6}
    },
    [6] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201105,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      sentence = "最近制作的几个标本中，不那么常规的反而占了大多数。",
      voice = 2,
      next = {7}
    },
    [7] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201105,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      sentence = "既然有这样的机会，不如趁机补一补相关的专业知识。",
      voice = 2,
      next = {8}
    },
    [8] = {
      beijing = 1673,
      dhead = 107,
      dialog = 1,
      music = "35_DS_Jazz",
      renming = "$u",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201105,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      sentence = "不愧是你！那我们的大教授有学到些什么吗？",
      next = {9}
    },
    [9] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201105,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      sentence = "意识到了自己对于标本的认知似乎有一些误区。",
      voice = 2,
      next = {10}
    },
    [10] = {
      beijing = 1673,
      dialog = 3,
      music = "35_DS_Jazz",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201106,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      roleanim = 1.1,
      sentence = "他移开电脑把我捞入怀中，把身旁的书翻到绘有植物标本插图的一页，娓娓而谈。 ",
      next = {11}
    },
    [11] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201106,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      roleanim = 1.1,
      sentence = "在收藏领域，标本的意义大多是保存下生物的某个瞬间，就像拍下一张照片，录下一段影像。",
      voice = 2,
      next = {12}
    },
    [12] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201106,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      roleanim = 1.1,
      sentence = "可以理解为是对过去的记录。",
      voice = 2,
      next = {13}
    },
    [13] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2154000,
      role2 = 201105,
      role3 = 201201,
      role4 = 201301,
      role5 = 2154404,
      roleanim = 1.1,
      ruchang = 9,
      sentence = "但从科学研究的角度，则大多服务于相关课题的研究和分析。",
      voice = 2,
      next = {14}
    },
    [14] = {
      beijing = 1673,
      dhead = 111,
      dialog = 1,
      music = "35_DS_Jazz",
      renming = "$u",
      renwu = "npc",
      sentence = "这么听来，倒更像是为未来做的某种储备？",
      next = {15}
    },
    [15] = {
      beijing = 1673,
      dialog = 3,
      music = "35_DS_Jazz",
      renwu = "npc",
      sentence = "身后的人点了点头，下巴轻柔地磨蹭着我头顶的发丝。",
      next = {16}
    },
    [16] = {
      beijing = 1673,
      dialog = 3,
      music = "35_DS_Jazz",
      renwu = "npc",
      sentence = "鼻腔内他的气息与酒香糅杂，让我在专心“听讲”之余，又贪恋地蹭上他的脖颈。 ",
      next = {17}
    },
    [17] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2153000,
      role2 = 202101,
      role3 = 202201,
      role4 = 202301,
      roleanim = 1.1,
      ruchang = -1,
      sentence = "我们剪下的绣球侧枝会让植株生长得更加茂盛，你带来的种子或许会在未来的某一天发芽。",
      voice = 2,
      next = {18}
    },
    [18] = {
      beijing = 1673,
      dialog = 2,
      idx = 2,
      male = 2,
      music = "35_DS_Jazz",
      renming = "许墨",
      renwu = "npc",
      role1 = 2153000,
      role2 = 202101,
      role3 = 202201,
      role4 = 202301,
      roleanim = 1.1,
      sentence = "那枚集章卡也还有很多空余等待我们填满。",
